import re
def format_log_line(timestamp: str, level: str, source: str, message: str) -> str:
    pattern = re.compile(r'(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})')
    match = pattern.match(timestamp)
    if match:
        timestamp_str = match.group(1)
        level_str = match.group(2)
        source_str = match.group(3)
        if level_str.lower() == 'error':
            return f'Error: {message}'
        elif level_str.lower() == 'warn':
            return f'Warning: {message}'
        else:
            return f'Log: {timestamp_str} {level_str} {source_str} {message}'

