def sparse_vector_dot(v1: dict[int, float], v2: dict[int, float]) -> float:
    """
    এই ফাংশনটি দুটি sparse ভেক্টর `v1` এবং `v2` এর ডিকশনারি ইনপুট হিসেবে গ্রহণ করে এবং তাদের ডট প্রোডাক্ট হিসাব করে।
    প্রতিটি ডিকশনারি একটি ভেক্টর প্রতিনিধিত্ব করে যেখানে প্রতিটি ইনডেক্সের মান তার সংশ্লিষ্ট মান।
    যদি কোনও ইনডেক্স ডিকশনারিতে না থাকে, তবে তার মান শূন্য।
    ডট প্রোডাক্টের ফলাফল একটি ফ্লোট সংখ্যা (3 দশমিক স্থান পর্যন্ত রাউন্ড করা) হিসেবে ফেরত দেয়।
    """
    dot_product = 0.0
    for key in v1:
        if key in v2:
            dot_product += v1[key] * v2[key]
    return round(dot_product, 3)

