def sparse_vector_dot(v1: dict[int, float], v2: dict[int, float]) -> float:
    """
    দুটি স্পার্সিত ভেক্টর `v1` এবং `v2` এর ডট প্রোডাক্ট গণনা করুন;
    প্রতিটি ভেক্টর একটি ডিকশনারি, যেখানে কীগুলি ইনডেক্স এবং মানগুলি সংশ্লিষ্ট মান, এবং কোনও ইনডেক্স যা ডিকশনারিতে নেই তা শূন্য মান হিসেবে বিবেচনা করা হয়।
