def sparse_vector_dot(v1: dict[int, float], v2: dict[int, float]) -> float:
    """
    দুটি স্পার্স ভেক্টর `v1` এবং `v2` এর ডট প্রোডাক্ট গণনা করুন; প্রতিটি ভেক্টর একটি ডিকশনারি যা ইনডেক্সকে মান হিসেবে প্রতিনিধিত্ব করে। কোনও ইনডেক্স ডিকশনারিতে উপস্থিত না থাকলে, সেটিকে শূন্য মান হিসেবে বিবেচনা করা হয়। ফলাফলটি তিনটি দশমিক স্থান পর্যন্ত রাউন্ড করে ফেরত দিন।
    """
    dot_product = 0.0
    for key in v1:
        if key in v2:
            dot_product += v1[key] * v2[key]
    return round(dot_product, 3)

