def parse_kv_pairs(text: str) -> dict[str, str]:
    pairs = text.split(';')
    pairs = [pair.strip().split('=') for pair in pairs]
    result = {}
    for pair in pairs:
        key, value = pair[0], pair[1]
        key = key.strip()
        value = value.strip()
        if key in result:
            result[key] += value
        else:
            result[key] = value
    return result

