def serve_static(web_root: str, request_path: str) -> tuple[int, bytes]:
    """
    একটি ফাইল খুঁজে বের করে যা `web_root` ডিরেক্টরিতে `request_path` এর সাথে মিলছে এবং একটি (স্ট্যাটাস, body) টুপল রিটার্ন করে।
    `request_path` শুরু হয় `/` দিয়ে এবং URL-ডেকোটেড; এটি সেই ফাইলকে নির্দেশ করে যা `web_root` এর মধ্যে রয়েছে (উদাহরণস্বরূপ, `/css/site.css` `css/site.css` এর সাথে মিলছে), এবং `/` ফাইলটি নির্দেশ করে `index.html`। যদি একটি নিয়মিত ফাইল থাকে, তবে `status` হবে `200` এবং `body` হবে ফাইলের বিষয়বস্তু হিসেবে বাইটস; অন্যথায়, ফাংশনটি `(404, b"Not Found")` রিটার্ন করবে।
    """
    if not web_root.startswith(request_path):
        return (404, b"Not Found")
    try:
        content = open(web_root, 'r').read()
        return (200, content)
    except IOError:
        return (404, b"Not Found")

