def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    if n == 0:
        return 1

    board = [[0] * n for _ in range(n)]

    for row, col in blocked:
        board[row][col] = 1

    def is_safe(r, c):
        return board[r][c] == 0 and r >= 0 and r < n and c >= 0 and c < n and board[r][c] == 0

    def solve(r, c):
        if r == n:
            return 1

        if is_safe(r, c):
            board[r][c] = 1
            count = solve(r + 1, c + 1)
            board[r][c] = 0
            count += solve(r + 1, c)
            count += solve(r, c + 1)
            return count

        return 0

    return solve(0, 0)

