        raise ValueError("অবৈধ expression")

    tokens = expression.split()
    stack = []

    for token in tokens:
        if token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                stack.pop()
            if stack:
                stack.pop()
            else:
