        except requests.ConnectionError:
            print("ডাউনলোড ব্যর্থ: সংযোগে সমস্যা")
            return None
        except Exception:
            print("ডাউনলোড ব্যর্থ: অপ্রত্যাশিত ত্রুটি")
            return None

