def count_queens(n: int, blocked: list[tuple[int, int]]) -> int:
    # blocked squares are ignored
    blocked = set(blocked)
    # count the number of valid placements
    count = 0
    # for each row, count the number of valid placements
    for row in range(n):
        # for each column, count the number of valid placements
        for col in range(n):
            # check if the square is blocked
            if (row, col) in blocked:
                continue
            # check if the square is occupied by a queen
            occupied = False
