def count_shortest_paths(n: int, edges: list[tuple[int, int]], source: int, target: int) -> int:
    graph = {}
    for u, v in edges:
        if u not in graph:
            graph[u] = []
        graph[u].append(v)

    queue = [(source, 0)]
    visited = set()
    shortest_paths = 0

    while queue:
        node, path_length = queue.pop(0)
        if node == target:
            shortest_paths += 1
            continue
        if node in visited:
            continue
        visited.add(node)

        if node in graph:
            for neighbor in graph[node]:
                queue.append((neighbor, path_length + 1))

    return shortest_paths

