    """
    একটি বার্তা এনক্রিপ্ট করে এবং তারপর এনক্রিপ্টেড বার্তাটি ডিক্রিপ্ট করে।
    """
    encrypted_message = bytearray()
    for byte in plaintext:
        encrypted_message.append(byte ^ key)
    return bytes(encrypted_message)

