    এই ফাংশনটি একটি সিস্টেমের একাধিক কনজুগেটড শর্ত (মডুলো সমীকরণ) সমাধান করে। প্রতিটি টুপল `(r, m)` এর তালিকা `congruences` মানে যে কোনও অজানা পূর্ণসংখ্যা `x` অবশ্যই `x % m == r % m` শর্ত পূরণ করতে হবে, যেখানে `m` একটি ধনাত্মক পূর্ণসংখ্যা; `r` নেতিবাচক বা বড় হতে পারে, এবং মডুলার কোঅর্ডিনেটগুলি একে অপরের সাথে জোড়া নয়; যদি সিস্টেমটি একটি সমাধান থাকে, তবে ফাংশনটি একটি টুপল `(x, L)` রিটার্ন করে, যেখানে `L` হলো সব মডুলার সংখ্যার লঘিষ্ঠ সাধারণ গুণিতক (LCM), এবং `x` হলো সব মডুলার সংখ্যার মধ্যে একটি অনন্য সমাধান যা `0 <= x < L`। যদি সিস্টেমটি কোনও সমাধান না থাকে, তবে এটি `None` রিটার্ন করে। একটি খালি তালিকা হলে, এটি `(0, 1)` রিটার্ন করে।
    """
    if len(congruences) == 0:
        return (0, 1)

    # প্রতিটি মডুলার সংখ্যার জন্য লঘিষ্ঠ সাধারণ গুণিতক (LCM) গণনা করুন
    lcm = 1
    for congruence in congruences:
        lcm = lcm * congruence[1]
        for r in congruence[0]:
            lcm = lcm * r

    # সব মডুলার সংখ্যার লঘিষ্ঠ সাধারণ গুণিতক (LCM) গণনা করুন
    lcm_all = lcm
    for congruence in congruences:
        lcm_all = lcm_all * congruence[1]
        for r in congruence[0]:
            lcm_all = lcm_all * r

    # যদি সব মডুলার সংখ্যার লঘিষ্ঠ সাধারণ গুণিতক (LCM) সমান হয়, তাহলে সিস্টেমটি সমাধান করে
    if lcm_all == lcm_all:
        return (lcm_all, lcm_all)

    # যদি কোনও সমাধান না থাকে, তাহলে `None` রিটার্ন করুন
    return None

