def pack_bins(sizes: list[int], capacity: int) -> list[list[int]]:
    """
    প্যাকড বিনের তালিকা ফেরত দেয়, যেখানে প্রতিটি কন্টেইনারের আকার এবং উপাদানগুলি তাদের অবস্থানের ক্রম অনুযায়ী সাজানো।
    যদি কোনও উপাদান `capacity` এর বেশি হয়, তবে একটি ValueError উত্থাপিত হয়।
    যদি কোনও কন্টেইনার খোলা না থাকে, তবে নতুন একটি কন্টেইনার খোলা হয়।
    """
    containers = []
    for size in sizes:
        if size > capacity:
            raise ValueError("অবৈধ আকার")
        container = []
        for i in range(0, size + 1):
            if container:
                container.append(size)
            else:
                container = [size]
        containers.append(container)
    return containers

