    """
    এই ফাংশনটি প্রদত্ত তালিকা `guests` এর সব সম্ভাব্য বিন্যাস ফেরত দেয় যেখানে কোনও জোড়া প্রতিবেশী অতিথি `conflicts` তালিকায় অন্তর্ভুক্ত হয় না।
    প্রতিটি বিন্যাস একটি তালিকা যা `guests` এর বাম থেকে ডানে সাজানো, এবং নামগুলি সাজানো হয় অভিজাতভাবে।
    যদি `guests` খালি হয়, তাহলে ফলাফল হবে `[[]]` (একটি একক খালি বিন্যাস)।
    যদি কোনও বৈধ বিন্যাস না থাকে, তাহলে ফলাফল হবে খালি তালিকা।
    """
    def is_valid(arrangement: list[str], conflicts: list[tuple[str, str]]) -> bool:
        for i in range(len(arrangement) - 1):
            if arrangement[i] == arrangement[i + 1]:
                return False
        return True

    def generate_arrangements(current_arrangement: list[str], remaining_guests: list[str]) -> list[list[str]]:
        if not remaining_guests:
            return [current_arrangement]

        arrangements = []
        for i in range(len(remaining_guests)):
            next_guest = remaining_guests[i]
            if next_guest not in current_arrangement:
                new_arrangement = current_arrangement + [next_guest]
                new_remaining_guests = remaining_guests[:i] + remaining_guests[i+1:]
                arrangements.extend(generate_arrangements(new_arrangement, new_remaining_guests))
        return arrangements

    return generate_arrangements([], guests)

