    """
    এই ফাংশনটি প্রদত্ত তালিকা এবং কনফ্লিক্টগুলো দিয়ে সম্ভাব্য সব seating arrangements ফেরত দেয়।

    Args:
        guests (list[str]): guests এর তালিকা, যেখানে প্রতিটি নাম একটি আলাদা নাম।
        conflicts (list[tuple[str, str]]): কনফ্লিক্টগুলো, যেখানে একটি tuple হলো (a, b) যেখানে a এবং b কে seating এর জন্য বিবেচনা করা হয়।

    Returns:
        list[list[str]]: seating arrangements এর তালিকা, যা sorted lexicographically.
    """
    def is_valid(arrangement: list[str], conflicts: list[tuple[str, str]]) -> bool:
        for a, b in conflicts:
            if a in arrangement and b in arrangement:
                return False
        return True

    def generate_arrangements(current_arrangement: list[str], remaining_guests: list[str]):
        if not remaining_guests:
            return current_arrangement

        for i in range(len(remaining_guests)):
            next_guest = remaining_guests[i]
            if next_guest not in current_arrangement:
                new_arrangement = current_arrangement + [next_guest]
                new_remaining_guests = remaining_guests[:i] + remaining_guests[i+1:]
                new_arrangements = generate_arrangements(new_arrangement, new_remaining_guests)
                return new_arrangements

        return None

    return generate_arrangements([], guests)

