def reset_password(email: str, new_password: str, set_password) -> bool:
    """
    এই ফাংশনটি একটি অ্যাকাউন্ট এর পাসওয়ার্ড রিসেট করে এবং এটি লগ করে। যদি নতুন পাসওয়ার্ডের দৈর্ঘ্য ৮ এর কম হয়, তবে এটি কিছু করে না। এটি একটি লগ রেকর্ড তৈরি করে `WARNING` স্তরে, যা `email` এবং `rejected` শব্দ সহ, এবং একটি `ValueError` উত্থাপন করে। অন্যথায়, এটি `set_password(email, new_password)` কল করে, যা `True` রিটার্ন করে যদি পাসওয়ার্ড রিসেট হয়, এবং `False` যদি না থাকে। তারপর এটি `INFO` স্তরে একটি লগ রেকর্ড তৈরি করে, যা `email` এর মান সহ, এবং `updated` শব্দটি যোগ করে যদি `set_password` `True` রিটার্ন করে, অন্যথায় `unknown`।
    """
    if len(new_password) < 8:
        return False
    try:
        set_password(email, new_password)
        return True
    except ValueError:
        return False

