def format_table(rows: list[list[str]], aligns: str) -> str:
    """
    এই ফাংশনটি একটি তালিকা `rows` (প্রতিটি সারি একটি তালিকা, প্রতিটি সারিতে একই সংখ্যক সেল রয়েছে) কে ফিক্সড-উভয়-কলাম টেক্সট হিসেবে উপস্থাপন করে এবং এটি একটি একক স্ট্রিং হিসেবে রিটার্ন করে। `aligns` হলো একটি স্ট্রিং যার এক অক্ষর প্রতি কলাম: `"l"` মানে বাম-অঙ্গুলিত, `"r"` ডান-অঙ্গুলিত, এবং `"c"` কেন্দ্র। কলামের প্রস্থ হলো এর সবচেয়ে দীর্ঘ সেলটির দৈর্ঘ্য, এবং প্রতিটি সেলটি ডান দিকে অতিরিক্ত স্পেস দিয়ে পাম্প করা হয় যাতে এটি সেই প্রস্থের সমান হয়: একটি বাম-অঙ্গুলিত সেল ডান দিকে, একটি ডান-অঙ্গুলিত সেল বাম দিকে, এবং একটি কেন্দ্র সেল উভয় দিকে, যেখানে বাকি স্থান ডান দিকে গেলে চলে যায় যদি সংখ্যাটি অ-পরিমিত হয়। সারিগুলো সেল দিয়ে সংযুক্ত হয় `" | "` (স্পেস, ভেক্টর বার, এবং স্পেস), এবং সারিগুলো `\n` (নিয়মিত লাইন) দিয়ে সংযুক্ত হয়, একটি ট্রাভার্সাল লাইন ছাড়াই। শেষের স্পেসগুলো সংরক্ষণ করা হয়। যদি `rows` খালি হয়, তবে ফাংশনটি একটি খালি স্ট্রিং রিটার্ন করে।
    """
    if len(rows) == 0:
        return ""
    for row in rows:
        if len(row) == 0:
            continue
        for cell in row:
            if aligns == "l":
                if len(cell) > 1:
                    cell += " " * (len(cell) - 1)
            elif aligns == "r":
                if len(cell) > 1:
                    cell += " " * (len(cell) - 1)
            elif aligns == "c":
                if len(cell) > 1:
                    cell += " " * (len(cell) - 1)
    return "\n".join(row + "\n" for row in rows)

