def rotate_rings(matrix: list[list[int]], k: int) -> list[list[int]]:
    n = len(matrix)
    if n == 0:
        return []

    # outer ring
    outer_ring = []
    for i in range(n):
        outer_ring.append(matrix[i][n - 1 - i])

    # inner rings
    for i in range(1, n):
        inner_ring = []
        for j in range(n - 1 - i):
            inner_ring.append(matrix[j][n - 1 - i - j])
        outer_ring.extend(inner_ring)

    # central ring
    if n % 2 == 1:
        central_ring = []
        for i in range(n):
            central_ring.append(matrix[i][n - 1 - i])
        outer_ring.extend(central_ring)

    # rotate clockwise
    rotated_outer_ring = []
    for i in range(n):
        rotated_outer_ring.append(outer_ring[i][n - 1 - i])

    # rotate counterclockwise
    rotated_inner_ring = []
    for i in range(n - 1 - k, n - 1 - k + 1):
        rotated_inner_ring.append(inner_ring[i][n - 1 - i])

    rotated_outer_ring.extend(rotated_inner_ring)

    return rotated_outer_ring

