    প্রশিক্ষণের সময় ব্যবহৃত প্যারেন্টেসির অগ্রাধিকারটি Python এর। উদাহরণস্বরূপ, যদি `{"price": 12.5, "stock": 3}` হয়, তবে `price > 10 and stock < 5` এক্সপ্রেশনটি `True` রিটার্ন করবে, এবং `not active` এক্সপ্রেশনটি `False` রিটার্ন করবে।
    যদি `expression` একটি বৈধ এক্সপ্রেশন না হয়, বা এটি `record` এ কোনও কী না হলে একটি `ValueError` উত্থাপন করবে।
    """
    if not isinstance(expression, str):
        raise ValueError("এক্সপ্রেশন অবশ্যই একটি স্ট্রিং হতে হবে।")
    if not isinstance(record, dict):
        raise ValueError(" রেকর্ড অবশ্যই একটি ডিকশনারি হতে হবে।")
    if not expression.startswith('(') or not expression.endswith(')'):
        raise ValueError("এক্সপ্রেশন অবশ্যই একটি স্ট্রিং হতে হবে।")
    try:
        return expression.split('(')[1].strip() in record
