def parse_csv(text: str) -> list[list[str]]:
    """
    CSV টেক্সটকে রেকর্ড লিস্টে পার্স করুন।
    """
    lines = text.split('\n')
    records = []
    for line in lines:
        record = []
        for field in line.split(','):
            if field.startswith('"') and field[1:] not in field.split(',')[0]:
                record.append(field)
            else:
                record.append(field)
        records.append(record)
    return records

