def render_report_header(template: str, report: dict) -> str:
    """
    একটি Jinja2 টেমপ্লেট ব্যবহার করে রিপোর্টের হেডার রেন্ডার করুন
    """
    report = report.copy()
    for key in report:
        if key not in report:
            report[key] = ""
        else:
            report[key] = str(report[key])
    return template.render(report)

