    stock = {}
    waiting = []

    for event in events:
        kind, item, quantity = event

        if kind == 'receive':
            stock[item] = quantity
        else:
            if stock.get(item, 0) >= quantity:
                stock[item] = quantity
            else:
                waiting.append((item, quantity))

    return (stock, waiting)

