            if op[1] == 'deposit':
                if not op[2] in balances:
                    failed.append(0)
                else:
                    balance = balances[op[1]]
                    if balance < 0:
                        failed.append(0)
                    else:
                        balance += op[2]
                        failed.append(0)
            elif op[1] == 'withdraw':
                if not op[2] in balances:
                    failed.append(0)
                else:
                    balance = balances[op[1]]
                    if balance < 0:
                        failed.append(0)
                    else:
                        balance -= op[2]
                        failed.append(0)
            elif op[1] == 'transfer':
                if not op[2] in balances:
                    failed.append(0)
                else:
                    source = op[1]
                    target = op[2]
                    amount = op[3]
