                        failed.append(0)
                    else:
                        balance -= amount
                        failed.append(0)
                if balance < 0:
                    failed.append(0)
                else:
                    balance += amount
                    failed.append(0)
            elif op[1] == 'freeze':
                if not op[2] in balances:
                    failed.append(0)
                else:
                    frozen_account = op[1]
                    if frozen_account in balances:
                        failed.append(0)

